import{_ as e,o as t,c as n,a5 as r}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"HJ99 自守数","description":"描述 自守数是指一个数的平方的尾数等于该数自身的自然数。例如：25^2 625，76^2 5776，9376^2 87909376。请求出n(包括n)以内的自守数的个数 数据范围： 1≤ n ≤10000 输入描述： int型整数 输出描述： n以内自守数的数量。 示例1 输入：。","frontmatter":{"title":"HJ99 自守数","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"描述 自守数是指一个数的平方的尾数等于该数自身的自然数。例如：25^2 625，76^2 5776，9376^2 87909376。请求出n(包括n)以内的自守数的个数 数据范围： 1≤ n ≤10000 输入描述： int型整数 输出描述： n以内自守数的数量。 示例1 输入：。","sidebarWeight":70,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为简单[31个]/HJ99 自守数.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ99 自守数.md","filePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ99 自守数.md"}'),o={name:"posts/前端面试与实战/03-算法训练/华为简单[31个]/HJ99 自守数.md"};function s(i,a,d,h,l,c){return t(),n("div",null,[...a[0]||(a[0]=[r('<div><h1 id="hj99-自守数" tabindex="-1">HJ99 自守数 <a class="header-anchor" href="#hj99-自守数" aria-label="Permalink to &quot;HJ99 自守数&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ99 自守数”的核心思路，并能把它用于实际开发或面试表达。 <strong>描述</strong> 自守数是指一个数的平方的尾数等于该数自身的自然数。例如：25^2 = 625，76^2 = 5776，9376^2 = 87909376。请求出n(包括n)以内的自守数的个数 数据范围： 1≤<em>n</em>≤10000 <strong>输入描述：</strong> int型整数 <strong>输出描述：</strong> n以内自守数的数量。 <strong>示例1</strong> 输入： 6 ==复制== 输出： 4 ==复制== 说明： 有0，1，5，6这四个自守数 <strong>示例2</strong> 输入： 1 ==复制== 输出： 2 ==复制== 说明： 有0, 1这两个自守数</p></blockquote><p>要找出n以内的自守数数量，我们可以遍历从0到n的每一个数字，计算它的平方，然后检查这个平方数的尾数是否等于原数。如果等于，那么这个数就是自守数。</p><p>以下是Python代码示例：</p><h1 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to &quot;输入&quot;">​</a></h1><p>n = int(input())</p><h1 id="初始化自守数的计数器" tabindex="-1">初始化自守数的计数器 <a class="header-anchor" href="#初始化自守数的计数器" aria-label="Permalink to &quot;初始化自守数的计数器&quot;">​</a></h1><p>count = 0</p><h1 id="遍历0到n-包括n" tabindex="-1">遍历0到n，包括n <a class="header-anchor" href="#遍历0到n-包括n" aria-label="Permalink to &quot;遍历0到n，包括n&quot;">​</a></h1><p>for i in range(n + 1):</p><h1 id="计算当前数字的平方" tabindex="-1">计算当前数字的平方 <a class="header-anchor" href="#计算当前数字的平方" aria-label="Permalink to &quot;计算当前数字的平方&quot;">​</a></h1><p>square = i * i</p><h1 id="将当前数字和它的平方转换为字符串" tabindex="-1">将当前数字和它的平方转换为字符串 <a class="header-anchor" href="#将当前数字和它的平方转换为字符串" aria-label="Permalink to &quot;将当前数字和它的平方转换为字符串&quot;">​</a></h1><p>num_str = str(i) square_str = str(square)</p><h1 id="检查平方数的尾数是否等于原数" tabindex="-1">检查平方数的尾数是否等于原数 <a class="header-anchor" href="#检查平方数的尾数是否等于原数" aria-label="Permalink to &quot;检查平方数的尾数是否等于原数&quot;">​</a></h1><p>if square_str.endswith(num_str):</p><h1 id="如果是-增加自守数计数器" tabindex="-1">如果是，增加自守数计数器 <a class="header-anchor" href="#如果是-增加自守数计数器" aria-label="Permalink to &quot;如果是，增加自守数计数器&quot;">​</a></h1><p>count += 1</p><h1 id="输出自守数的数量" tabindex="-1">输出自守数的数量 <a class="header-anchor" href="#输出自守数的数量" aria-label="Permalink to &quot;输出自守数的数量&quot;">​</a></h1><p>print(count) 这段代码通过循环遍历0到n的每一个数字，并计算每个数字的平方。然后，它将数字和它的平方都转换为字符串，并使用<code>str.endswith()</code>方法检查平方数的尾部是否与原数字相匹配。如果匹配，说明这是一个自守数，将自守数计数器<code>count</code>加1。循环结束后，输出自守数的总数。</p><p>这种方法直观且易于实现，适用于解决此问题。</p></div>',1)])])}const _=e(o,[["render",s]]);export{u as __pageData,_ as default};
